using Godot;
using System;
using System.Globalization;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void generator_inspector(Control o)
    {
        var entry=Dict(o,"_library_entry");string kind=Get(entry,"kind","").AsString();var inspector=Field<VBoxContainer>(o,"inspector");heading(inspector,Get(entry,"label","Library").AsString());label(inspector,Get(entry,"description",Get(entry,"category","")).AsString());using var layoutOps=new AudioWorkspaceLayoutOperations();var layout=Field<Node>(o,"_layout");
        if(kind=="generator")
        {
            var actions=new HFlowContainer();inspector.AddChild(actions);ActionButton(actions,"\u25b6 Preview",()=>generate_preview(o));ActionButton(actions,"+ Add to timeline",()=>add_preview(o));if(entry["id"].AsString()=="sample_grains")ActionButton(inspector,"Choose grain source\u2026",()=>o.Call("choose_generator_sample"));var settings=layoutOps.fold(layout,inspector,"sound_settings","Customize sound",false);foreach(var raw in Get(entry,"parameters",new GArray()).AsGodotArray()){var info=raw.AsGodotDictionary();string key=info["id"].AsString();NumberAction(o,settings,info["label"].AsString(),Get(Dict(o,"_generator_settings"),key,Get(info,"default",0)).AsDouble(),Get(info,"min",0).AsDouble(),Get(info,"max",1).AsDouble(),Get(info,"step",.01).AsDouble(),value=>{Dict(o,"_generator_settings")[key]=value;Field<Timer>(o,"_preview_timer").Start();});}ActionButton(settings,"Modulation\u2026",()=>o.Call("modulator_dialog",true));NumberAction(o,settings,"Random seed",o.Get("_generator_seed").AsInt64(),0,2147483647,1,value=>{o.Set("_generator_seed",(long)value);Field<Timer>(o,"_preview_timer").Start();});var variationsActions=new HFlowContainer();inspector.AddChild(variationsActions);ActionButton(variationsActions,"New variation",()=>{o.Set("_generator_seed",o.Get("_generator_seed").AsInt64()+1);generate_preview(o);});ActionButton(variationsActions,"Randomize",()=>{o.Set("_generator_seed",GD.Randi()%2147483647);generate_preview(o);});Menu(o,variationsActions,"Save",new GArray{Entry("Save sound preset\u2026",()=>o.Call("save_preset","generator")),Entry("Save audio file\u2026",()=>o.Call("save_preview_audio"))});var variations=Items(o,"_variations");if(variations.Count>0){var host=layoutOps.fold(layout,inspector,"sound_variations","Compare recent variations",false);for(int i=0;i<variations.Count;i++){var variation=variations[i].AsGodotDictionary();ActionButton(host,"\u25b6 Variation "+(i+1)+" · "+variation["stream"].As<AudioStreamWav>().GetLength().ToString("F2",CultureInfo.InvariantCulture)+"s",()=>select_variation(o,variation));}}
        }
        else if(kind=="instrument"){ActionButton(inspector,"Audition C4",()=>{using var instruments=new AudioInstrumentOperations();o.Call("audition_note",60,instruments.default_instrument(entry["id"].AsString()));});ActionButton(inspector,"Create instrument track",()=>library_add(o,entry));}
        else if(kind=="template")ActionButton(inspector,"Create from template",()=>library_add(o,entry));
        else if(kind=="asset"){ActionButton(inspector,"Preview",()=>library_preview(o,entry));ActionButton(inspector,"Add to timeline",()=>library_add(o,entry));}
        else if(kind=="preset")
        {
            var preset=entry["preset"].As<Resource>();using var library=new AudioLibraryOperations();var tags=library.preset_tags(preset);label(inspector,"Tags: "+(tags.Length>0?string.Join(", ",tags):"Untagged"));ActionButton(inspector,"Edit preset tags",()=>o.Call("_edit_preset_tags",entry));ActionButton(inspector,"Audition preset",()=>library_preview(o,entry));ActionButton(inspector,"Export native preset\u2026",()=>o.Call("export_native_preset",preset));ActionButton(inspector,"Apply editable preset",()=>library_add(o,entry));string path=entry["path"].AsString(),digest=Godot.FileAccess.GetSha256(path);ActionButton(inspector,"Organize in folder\u2026",()=>name_dialog(o,"Preset folder (searchable, slash-separated)",preset.Get("folder").AsString(),Callable.From<string>(folder=>{using var store=new AudioPresetStoreOperations();string problem=store.rename(path,digest,entry["label"].AsString(),folder);if(problem.Length>0)notice(o,problem);else Field<Control>(o,"library").Call("reload");}),true));ActionButton(inspector,"Rename preset",()=>name_dialog(o,"Rename preset",entry["label"].AsString(),Callable.From<string>(text=>{using var store=new AudioPresetStoreOperations();string problem=store.rename(path,digest,text,"__preserve");if(problem.Length>0)notice(o,problem);else Field<Control>(o,"library").Call("reload");}),false));ActionButton(inspector,"Duplicate preset",()=>{var copy=preset.Duplicate(true);using var crypto=new Crypto();copy.Set("id",Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant());copy.Set("label",copy.Get("label").AsString()+" copy");o.Call("_persist_preset",copy);});ActionButton(inspector,"Move preset to recovery",()=>{using var store=new AudioPresetStoreOperations();string problem=store.remove(path,digest);if(problem.Length>0){notice(o,problem);return;}Field<Control>(o,"library").Call("reload");o.Set("_library_entry",new Settings());refresh_inspector(o);});
        }
        if(kind=="preset"){var options=layoutOps.fold(layout,inspector,"preset_options","Preset options",false);foreach(var child in inspector.GetChildren())if(child is Button button&&button.Text is not ("Audition preset" or "Apply editable preset"))child.Reparent(options);}
    }
}
